  <script>
    (function () {
      const DURATION = 35;
      const DURATION_MS = DURATION * 1000;
      const startTime = performance.now();

      const _marks = [];
      const _labels = [
        { text: "Buyer", t: 0 },
        { text: "Gemini Agent", t: 0 },
        { text: "Spend Policy", t: 0 },
        { text: "Basis Theory Vault", t: 0 },
        { text: "Merchant", t: 0 },
        { text: "Base Sepolia", t: 0 }
      ];
      const _elements = [
        { name: "buyer", visibleFrom: 0, visibleTo: DURATION_MS },
        { name: "agent", visibleFrom: 0, visibleTo: DURATION_MS },
        { name: "spend", visibleFrom: 0, visibleTo: DURATION_MS },
        { name: "vault", visibleFrom: 0, visibleTo: DURATION_MS },
        { name: "merchant", visibleFrom: 0, visibleTo: DURATION_MS },
        { name: "chain", visibleFrom: 0, visibleTo: DURATION_MS }
      ];

      window.__theater = {
        duration: DURATION,
        marks: _marks,
        done: false,
        snapshot: function () {
          return {
            labels: _labels.map(function (l) {
              const copy = { text: l.text, t: l.t };
              if (l.orderId) copy.orderId = l.orderId;
              return copy;
            }),
            elements: _elements.map(function (e) {
              const copy = {
                name: e.name,
                visibleFrom: e.visibleFrom,
                visibleTo: e.visibleTo
              };
              if (e.orderId) copy.orderId = e.orderId;
              return copy;
            })
          };
        },
        _internal: {
          startTime: startTime,
          durationMs: DURATION_MS,
          labels: _labels,
          elements: _elements,
          addLabel: function (text, t, orderId) {
            const entry = { text: text, t: Math.round(t) };
            if (orderId) entry.orderId = orderId;
            _labels.push(entry);
          },
          addElement: function (name, t, orderId) {
            const existing = _elements.find(function (el) {
              return el.name === name && el.orderId === orderId;
            });
            if (existing) return existing;
            const entry = {
              name: name,
              visibleFrom: Math.round(t),
              visibleTo: DURATION_MS
            };
            if (orderId) entry.orderId = orderId;
            _elements.push(entry);
            return entry;
          },
          closeElement: function (name, t) {
            const existing = _elements.find(function (el) {
              return el.name === name;
            });
            if (existing && existing.visibleTo === DURATION_MS) {
              existing.visibleTo = Math.round(t);
            }
          }
        }
      };
    })();
