  <script type="module">
    import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js";

    const rawEvents = JSON.parse(document.getElementById("events").textContent.trim());
    const theater = window.__theater;
    const internal = theater._internal;
    const startTime = internal.startTime;

