      merchantGroup.add(awning);

      const leftWindow = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.68, 0.06), merchantWinMat);
      leftWindow.position.set(-0.42, 0.98, 0.71);
      merchantGroup.add(leftWindow);

      const rightWindow = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.68, 0.06), merchantWinMat);
      rightWindow.position.set(0.42, 0.98, 0.71);
      merchantGroup.add(rightWindow);

      const signBoard = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.28, 0.1), merchantWinMat);
      signBoard.position.set(0, 2.12, 0.45);
      merchantGroup.add(signBoard);

      merchantGlowLight = new THREE.PointLight(0xffdf80, 0, 4.2);
      merchantGlowLight.position.set(0, 1.25, 1.2);
      merchantGroup.add(merchantGlowLight);
    }

    function setMerchantLit(lit) {
      if (lit) {
        merchantBodyMat.color.setHex(0xe8d9be);
        merchantAwningMat.color.setHex(0x3a322b);
        merchantWinMat.color.setHex(0xfff1a8);
        merchantWinMat.emissive.setHex(0xffc940);
        merchantWinMat.emissiveIntensity = 0.85;
        merchantGlowLight.intensity = 1.6;
      } else {
        merchantBodyMat.color.setHex(0x24211e);
        merchantAwningMat.color.setHex(0x1b1917);
        merchantWinMat.color.setHex(0x151311);
        merchantWinMat.emissive.setHex(0x000000);
        merchantWinMat.emissiveIntensity = 0.0;
        merchantGlowLight.intensity = 0;
      }
    }

    // 6. BASE SEPOLIA CHAIN STATION: Row of red linked blocks
    const chainGroup = createPedestal(X_POS.chain);
    const settledBlockMesh = new THREE.Group();
    let ledgerPulseRing;
    let newBlkMesh;
    {
      const redBlockMat = new THREE.MeshStandardMaterial({
        color: COL_RED,
        roughness: 0.45,
        metalness: 0.15
      });
      const linkMat = new THREE.MeshStandardMaterial({ color: COL_INK, roughness: 0.5 });

      const xs = [-0.93, -0.31, 0.31];
      xs.forEach((bx, idx) => {
        const blk = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.44, 0.44), redBlockMat);
        blk.position.set(bx, 0.65, 0);
        blk.castShadow = true;
        chainGroup.add(blk);

        if (idx < xs.length - 1) {
          const link = new THREE.Mesh(
            new THREE.CylinderGeometry(0.055, 0.055, 0.22, 10),
            linkMat
          );
          link.rotation.z = Math.PI / 2;
          link.position.set(bx + 0.31, 0.65, 0);
          chainGroup.add(link);
        }
      });

      // 4th block that is appended to the chain row with a pulse when payment settles
      const newLink = new THREE.Mesh(
        new THREE.CylinderGeometry(0.055, 0.055, 0.22, 10),
        linkMat
      );
      newLink.rotation.z = Math.PI / 2;
      newLink.position.set(0.62, 0.65, 0);
      settledBlockMesh.add(newLink);

      newBlkMesh = new THREE.Mesh(
        new THREE.BoxGeometry(0.5, 0.5, 0.5),
        new THREE.MeshStandardMaterial({
          color: COL_RED_LIGHT,
          emissive: COL_RED,
          emissiveIntensity: 0.6,
          roughness: 0.35
        })
      );
      newBlkMesh.position.set(0.93, 0.65, 0);
      settledBlockMesh.add(newBlkMesh);

      ledgerPulseRing = new THREE.Mesh(
        new THREE.TorusGeometry(0.42, 0.045, 12, 28),
        new THREE.MeshStandardMaterial({
          color: 0xffb4ab,
          emissive: COL_RED_LIGHT,
          emissiveIntensity: 0.85
        })
      );
      ledgerPulseRing.position.set(0.93, 0.65, 0.28);
      settledBlockMesh.add(ledgerPulseRing);

      settledBlockMesh.visible = false;
      chainGroup.add(settledBlockMesh);
    }

    // Dynamic Moving Meshes: Yellow Packet & Red Coin
    function createYellowPacket() {
      const grp = new THREE.Group();
      const box = new THREE.Mesh(
        new THREE.BoxGeometry(0.66, 0.44, 0.16),
        new THREE.MeshStandardMaterial({
          color: COL_YELLOW,
          emissive: COL_YELLOW,
          emissiveIntensity: 0.3,
          roughness: 0.35
        })
      );
      grp.add(box);

      const flap = new THREE.Mesh(
        new THREE.BoxGeometry(0.68, 0.07, 0.18),
        new THREE.MeshStandardMaterial({ color: COL_INK })
      );
      flap.position.y = 0.08;
      grp.add(flap);

      const blueSealBadge = new THREE.Mesh(
        new THREE.CylinderGeometry(0.16, 0.16, 0.2, 20),
        new THREE.MeshStandardMaterial({
          color: COL_BLUE,
          emissive: COL_BLUE_LIGHT,
          emissiveIntensity: 0.5
        })
      );
      blueSealBadge.rotation.x = Math.PI / 2;
      blueSealBadge.visible = false;
      grp.add(blueSealBadge);
      grp.userData.seal = blueSealBadge;

      grp.visible = false;
      scene.add(grp);
      return grp;
    }

    const packetMesh0 = createYellowPacket();
    const packetMesh1 = createYellowPacket();

    // Red Coin (Buyer -> Merchant: the buyer pays the merchant, and the chain is not the recipient)
    const redCoinMesh = new THREE.Group();
    {
      const coinDisc = new THREE.Mesh(
        new THREE.CylinderGeometry(0.42, 0.42, 0.14, 28),
        new THREE.MeshStandardMaterial({
          color: COL_RED,
          emissive: COL_RED_LIGHT,
          emissiveIntensity: 0.35,
          roughness: 0.3,
          metalness: 0.25
        })
      );
      coinDisc.rotation.x = Math.PI / 2;
      redCoinMesh.add(coinDisc);

      const coinRim = new THREE.Mesh(
        new THREE.TorusGeometry(0.42, 0.04, 12, 28),
        new THREE.MeshStandardMaterial({ color: 0xffb4ab, roughness: 0.3 })
      );
      redCoinMesh.add(coinRim);

      redCoinMesh.visible = false;
      scene.add(redCoinMesh);
    }

    // HTML Overlay References
    const domLabels = {
      buyer: document.getElementById("lbl-buyer"),
      agent: document.getElementById("lbl-agent"),
      spend: document.getElementById("lbl-spend"),
      vault: document.getElementById("lbl-vault"),
      merchant: document.getElementById("lbl-merchant"),
      chain: document.getElementById("lbl-chain"),
      refusal: document.getElementById("lbl-refusal"),
      settled: document.getElementById("lbl-settled"),
      captionBar: document.getElementById("caption-bar"),
      captionText: document.getElementById("caption-text")
    };

    function projectToScreen(worldPos, el, clampMargin) {
      const vec = worldPos.clone().project(camera);
      let x = (vec.x * 0.5 + 0.5) * window.innerWidth;
      const y = (-vec.y * 0.5 + 0.5) * window.innerHeight;
      if (clampMargin) {
        x = Math.max(clampMargin, Math.min(window.innerWidth - clampMargin, x));
      }
      el.style.left = `${x.toFixed(1)}px`;
      el.style.top = `${y.toFixed(1)}px`;
    }

    function updateOverlayPositions() {
      projectToScreen(new THREE.Vector3(X_POS.buyer, -0.58, 1.3), domLabels.buyer, 0);
      projectToScreen(new THREE.Vector3(X_POS.agent, -0.58, 1.3), domLabels.agent, 0);
      projectToScreen(new THREE.Vector3(X_POS.spend, -0.58, 1.3), domLabels.spend, 0);
      projectToScreen(new THREE.Vector3(X_POS.vault, -0.58, 1.3), domLabels.vault, 0);
      projectToScreen(new THREE.Vector3(X_POS.merchant, -0.58, 1.3), domLabels.merchant, 0);
      projectToScreen(new THREE.Vector3(X_POS.chain, -0.58, 1.3), domLabels.chain, 0);

      projectToScreen(new THREE.Vector3(X_POS.vault, 3.05, 0), domLabels.refusal, 160);
      projectToScreen(new THREE.Vector3(7.6, 2.85, 0), domLabels.settled, 175);
    }

    // Replay State Flags (driven by events array in file order)
    const ev0 = rawEvents[0]; // refused
    const ev1 = rawEvents[1]; // settled

    const state = {
      ev0Started: false,
      ev0Refused: false,
      ev1Started: false,
      ev1Sealed: false,
      ev1CoinStarted: false,
      ev1MerchantPaid: false,
      ev1Settled: false
    };

    function setCaption(sentence, orderId, nowMs) {
      domLabels.captionBar.style.opacity = "1";
      domLabels.captionText.innerHTML = `${sentence} <span class="caption-oid">${orderId}</span>`;
      internal.addLabel(`${sentence} ${orderId}`, nowMs, orderId);
    }

    function lerpPos(x0, x1, u, arcHeight) {
      const clamped = Math.max(0, Math.min(1, u));
      const x = x0 + (x1 - x0) * clamped;
      const y = 1.35 + Math.sin(clamped * Math.PI) * arcHeight;
      return new THREE.Vector3(x, y, 0.85);
    }

    // Timeline Schedule (35s declared duration, 32.5s completion after final hold)
    // Beat 1 (ev0: refused): 1500ms -> 14000ms (12.5s beat)
    // Beat 2 (ev1: settled): 14000ms -> 28000ms (14.0s beat)
    // Final hold: 22500ms -> 32500ms, then done = true
    function updateTimeline(nowMs) {
      // Gentle camera drift that keeps all 6 stations well inside frame
      const driftAngle = nowMs * 0.00025;
      camera.position.x = Math.sin(driftAngle) * 0.22;
      camera.position.y = 6.0 + Math.cos(driftAngle * 0.8) * 0.08;
      camera.lookAt(0, 0.7, 0);

      // --- BEAT 1: Event 0 (refused) ---
      if (nowMs >= 1500 && !state.ev0Started) {
        state.ev0Started = true;
        theater.marks.push({
          t: Math.round(nowMs),
          kind: ev0.kind,
          orderId: ev0.orderId,
          element: "refusal"
        });
        packetMesh0.visible = true;
      }

      if (nowMs >= 1500 && nowMs < 4800) {
        if (nowMs < 3100) {
          // agent -> spend
          const u = (nowMs - 1500) / 1600;
          packetMesh0.position.copy(lerpPos(X_POS.agent, X_POS.spend, u, 0.55));
          spendGateBar.rotation.z = Math.sin(u * Math.PI) * 0.35;
        } else {
          // spend -> vault
          const u = (nowMs - 3100) / 1700;
          packetMesh0.position.copy(lerpPos(X_POS.spend, X_POS.vault - 0.55, u, 0.45));
          spendGateBar.rotation.z = 0;
        }
      }

      if (nowMs >= 4800 && !state.ev0Refused) {
        state.ev0Refused = true;
        packetMesh0.visible = false;

        // Vault shows refusal mark (blue seal with cross) and code text
        refusalSealGroup.visible = true;
        internal.addElement(`refusal:${ev0.orderId}`, nowMs, ev0.orderId);

        const refusalLabelPlain = `refused ${ev0.code} ${ev0.orderId}`;
        domLabels.refusal.innerHTML = `<div class="badge-main"><span class="badge-icon">✕</span><span>refused ${ev0.code}</span></div><span class="oid-token">${ev0.orderId}</span>`;
        domLabels.refusal.style.display = "inline-flex";
        internal.addLabel(refusalLabelPlain, nowMs, ev0.orderId);

        setCaption(`Vault refused the payment: ${ev0.code}`, ev0.orderId, nowMs);
      }

      // --- BEAT 2: Event 1 (settled) ---
      if (nowMs >= 14000 && !state.ev1Started) {
        state.ev1Started = true;
        // Clear 3D cross badge from vault face before the second order is processed
        refusalSealGroup.visible = false;
        internal.closeElement(`refusal:${ev0.orderId}`, nowMs);

        theater.marks.push({
          t: Math.round(nowMs),
          kind: ev1.kind,
          orderId: ev1.orderId,
          element: "coin"
        });
        packetMesh1.visible = true;
      }

      if (nowMs >= 14000 && nowMs < 19000) {
        if (nowMs < 15700) {
          // agent -> spend
          const u = (nowMs - 14000) / 1700;
          packetMesh1.position.copy(lerpPos(X_POS.agent, X_POS.spend, u, 0.55));
          spendGateBar.rotation.z = Math.sin(u * Math.PI) * 0.48;
        } else if (nowMs < 17400) {
          // spend -> vault
          const u = (nowMs - 15700) / 1700;
          packetMesh1.position.copy(lerpPos(X_POS.spend, X_POS.vault, u, 0.45));
          spendGateBar.rotation.z = 0;
        } else {
          // At vault: vault seals packet in blue (key inside vault glows in place without moving)
          packetMesh1.position.set(X_POS.vault, 1.35, 0.9);
          if (!state.ev1Sealed) {
            state.ev1Sealed = true;
            packetMesh1.userData.seal.visible = true;
            vaultBlueSealGroup.visible = true;
            vaultInteriorLight.intensity = 2.0;
          }
        }
      }

      // Only AFTER vault seals packet, red coin moves from Buyer company side to Merchant
      if (nowMs >= 19000 && !state.ev1CoinStarted) {
        state.ev1CoinStarted = true;
        packetMesh1.visible = false;
        vaultInteriorLight.intensity = 1.0;

        redCoinMesh.visible = true;
        redCoinMesh.position.set(X_POS.buyer, 1.35, 0.9);
        internal.addElement(`coin:${ev1.orderId}`, nowMs, ev1.orderId);
      }

      if (nowMs >= 19000 && nowMs < 22000) {
        const u = (nowMs - 19000) / 3000;
        // Buyer pays Merchant: red coin moves from buyer station to merchant station and stops there
        redCoinMesh.position.copy(lerpPos(X_POS.buyer, X_POS.merchant, u, 1.35));
        redCoinMesh.rotation.y = u * Math.PI * 2;
      }

      if (nowMs >= 22000 && !state.ev1MerchantPaid) {
        state.ev1MerchantPaid = true;
        // Coin rests at the Merchant (never enters the chain)
        redCoinMesh.position.set(X_POS.merchant, 1.25, 0.92);
        redCoinMesh.rotation.y = 0;
        setMerchantLit(true);
      }

      // Separate ledger cue on Base Sepolia chain: new red block appended with pulse, no coin entering it
      if (nowMs >= 22500 && !state.ev1Settled) {
        state.ev1Settled = true;
        settledBlockMesh.visible = true;
        internal.addElement(`ledger:${ev1.orderId}`, nowMs, ev1.orderId);

        const shortHash = ev1.txHash.slice(0, 10);
        const settledLabelPlain = `${ev1.amount} USDC ${shortHash} ${ev1.orderId}`;
        domLabels.settled.innerHTML = `<div class="badge-main"><span class="badge-icon">●</span><span>${ev1.amount} USDC · ${shortHash}</span></div><span class="oid-token">${ev1.orderId}</span>`;
        domLabels.settled.style.display = "inline-flex";
        internal.addLabel(settledLabelPlain, nowMs, ev1.orderId);

        setCaption(
          `Settled on Base Sepolia: ${ev1.amount} USDC, receipt ${shortHash}`,
          ev1.orderId,
          nowMs
        );
      }

      // Ledger inclusion pulse animation on the newly appended 4th chain block
      if (state.ev1Settled) {
        const dt = nowMs - 22500;
        if (dt < 2400) {
          const pulse = 1 + 0.28 * Math.sin((dt / 2400) * Math.PI * 3) * (1 - dt / 2400);
          newBlkMesh.scale.set(pulse, pulse, pulse);
          const ringScale = 1 + 0.45 * Math.sin((dt / 2400) * Math.PI * 2);
          ledgerPulseRing.scale.set(ringScale, ringScale, 1);
        } else {
          newBlkMesh.scale.set(1, 1, 1);
          ledgerPulseRing.scale.set(1.08, 1.08, 1);
        }
      }

      // Final state holds from 22.5s to 32.5s (well over 3-5s hold), then done = true
      if (nowMs >= 32500 && !theater.done) {
        theater.done = true;
      }
    }

    function tick() {
      const nowMs = performance.now() - startTime;
      updateTimeline(nowMs);
      updateOverlayPositions();
      renderer.render(scene, camera);
    }

    function animate() {
      tick();
      requestAnimationFrame(animate);
    }

    // Fallback interval ensures timeline advances accurately even if rAF is throttled
    const timerId = setInterval(function () {
      tick();
      if (theater.done) {
        clearInterval(timerId);
      }
    }, 50);

    window.addEventListener("resize", function () {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      updateOverlayPositions();
    });

    updateOverlayPositions();
    requestAnimationFrame(animate);
  </script>
</body>
</html>
